import{_ as d,o as r,c as a,a3 as e}from"./chunks/framework.DotqndlA.js";const c=JSON.parse('{"title":"IEC 60870-5-104 协议介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/iec104/index.md","filePath":"guide/protocols/iec104/index.md","lastUpdated":1786981506000}'),o={name:"guide/protocols/iec104/index.md"};function h(_,t,i,l,n,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="iec-60870-5-104-协议介绍" tabindex="-1">IEC 60870-5-104 协议介绍 <a class="header-anchor" href="#iec-60870-5-104-协议介绍" aria-label="Permalink to &quot;IEC 60870-5-104 协议介绍&quot;">​</a></h1><h2 id="协议概述" tabindex="-1">协议概述 <a class="header-anchor" href="#协议概述" aria-label="Permalink to &quot;协议概述&quot;">​</a></h2><p>IEC 60870-5-104 是 IEC 60870-5 系列中<strong>基于 TCP/IP 网络的远动通信协议</strong>，广泛用于变电站与调度中心（SCADA/EMS）之间的数据传输。它是 IEC 60870-5-101（串口）的网络化版本，将 APDU 封装在 TCP 之上。</p><p>EMS Simulate 基于 <code>c104</code> 库实现该协议，完整支持&quot;四遥&quot;体系（YC 遥测 / YX 遥信 / YK 遥控 / YT 遥调），可模拟测控装置、远动终端，也可作为主站连接真实设备。</p><h2 id="协议特性" tabindex="-1">协议特性 <a class="header-anchor" href="#协议特性" aria-label="Permalink to &quot;协议特性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td>默认端口</td><td>2404（TCP）</td></tr><tr><td>帧类型</td><td>I 帧（数据）、S 帧（确认）、U 帧（链路控制）</td></tr><tr><td>测点类型</td><td>YC 遥测、YX 遥信、YK 遥控、YT 遥调</td></tr><tr><td>ASDU 类型</td><td>完整支持全部 25 种 ASDU 类型</td></tr><tr><td>品质描述符</td><td>IV / NT / SB / BL / OV 等标准品质位</td></tr><tr><td>传输原因</td><td>周期、自发、总召唤、命令确认、时钟同步等</td></tr><tr><td>高级功能</td><td>总召唤、时钟同步、计数量召唤、遥调-遥测绑定</td></tr></tbody></table><h2 id="四遥体系" tabindex="-1">四遥体系 <a class="header-anchor" href="#四遥体系" aria-label="Permalink to &quot;四遥体系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>名称</th><th>典型 ASDU</th><th>说明</th></tr></thead><tbody><tr><td>YC</td><td>遥测</td><td>M_ME_NC_1 (13) 等</td><td>测量值（电压、电流、功率等）</td></tr><tr><td>YX</td><td>遥信</td><td>M_SP_NA_1 (1)、M_DP_NA_1 (3)</td><td>单点/双点状态（开关位置等）</td></tr><tr><td>YK</td><td>遥控</td><td>C_SC_NA_1 (45)、C_DC_NA_1 (46)</td><td>单点/双点命令（分/合闸）</td></tr><tr><td>YT</td><td>遥调</td><td>C_SE_NC_1 (50) 等</td><td>设定值命令（目标值下发）</td></tr></tbody></table><h2 id="常用-asdu-类型" tabindex="-1">常用 ASDU 类型 <a class="header-anchor" href="#常用-asdu-类型" aria-label="Permalink to &quot;常用 ASDU 类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型标识</th><th>ASDU</th><th>类别</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td>M_SP_NA_1</td><td>遥信</td><td>单点信息</td></tr><tr><td>3</td><td>M_DP_NA_1</td><td>遥信</td><td>双点信息</td></tr><tr><td>9</td><td>M_ME_NA_1</td><td>遥测</td><td>归一化值</td></tr><tr><td>11</td><td>M_ME_NB_1</td><td>遥测</td><td>标度化值</td></tr><tr><td>13</td><td>M_ME_NC_1</td><td>遥测</td><td>短浮点数（最常用）</td></tr><tr><td>21</td><td>M_ME_NC_1</td><td>遥测</td><td>计数量（累计值）</td></tr><tr><td>45</td><td>C_SC_NA_1</td><td>遥控</td><td>单点命令</td></tr><tr><td>46</td><td>C_DC_NA_1</td><td>遥控</td><td>双点命令</td></tr><tr><td>50</td><td>C_SE_NC_1</td><td>遥调</td><td>设定值命令（短浮点）</td></tr><tr><td>100</td><td>C_IC_NA_1</td><td>控制</td><td>总召唤命令</td></tr><tr><td>103</td><td>C_CS_NA_1</td><td>控制</td><td>时钟同步命令</td></tr></tbody></table><h2 id="品质描述符" tabindex="-1">品质描述符 <a class="header-anchor" href="#品质描述符" aria-label="Permalink to &quot;品质描述符&quot;">​</a></h2><p>遥测/遥信数据带 1 字节品质描述符（QDS）：</p><table tabindex="0"><thead><tr><th>位</th><th>标志</th><th>含义</th></tr></thead><tbody><tr><td>0</td><td>OV</td><td>溢出</td></tr><tr><td>2</td><td>BL</td><td>闭锁</td></tr><tr><td>3</td><td>SB</td><td>取代</td></tr><tr><td>4</td><td>NT</td><td>不刷新（非当前值）</td></tr><tr><td>7</td><td>IV</td><td>无效</td></tr></tbody></table><h2 id="通信过程" tabindex="-1">通信过程 <a class="header-anchor" href="#通信过程" aria-label="Permalink to &quot;通信过程&quot;">​</a></h2><p>一个典型的 IEC104 通信过程：</p><ol><li><strong>链路建立</strong>：客户端发送 STARTDT 激活（U 帧），服务端确认；</li><li><strong>总召唤</strong>：客户端发送总召唤命令（C_IC_NA_1），服务端上送全部测点；</li><li><strong>数据上送</strong>：遥测按周期/变化上送（I 帧），客户端回 S 帧确认；</li><li><strong>命令下发</strong>：遥控/遥调命令（I 帧）及服务端的确认响应；</li><li><strong>时钟同步</strong>：周期性时钟同步命令校准。</li></ol><h2 id="角色说明" tabindex="-1">角色说明 <a class="header-anchor" href="#角色说明" aria-label="Permalink to &quot;角色说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>行为</th></tr></thead><tbody><tr><td><strong>服务端（Server）</strong></td><td>模拟测控装置/远动设备，维护测点数据，响应总召唤、上送数据、执行遥控/遥调命令</td></tr><tr><td><strong>客户端（Client）</strong></td><td>模拟主站，连接服务端，执行总召唤、读取数据、下发命令、时钟同步</td></tr></tbody></table><blockquote><p>📄 详细操作见 <a href="./operation.html">IEC104 操作指南</a>，报文结构见 <a href="./packet-view.html">IEC104 报文查看</a>。</p></blockquote>',19)])])}const C=d(o,[["render",h]]);export{c as __pageData,C as default};
